import{_ as e,o as l,c as t,a2 as o}from"./chunks/framework.BjkiRu3Q.js";const d=JSON.parse('{"title":"Είσπραξη και παράδοση μετρητών","description":"","frontmatter":{},"headers":[],"relativePath":"el/plus/cash-management.md","filePath":"el/plus/cash-management.md"}'),i={name:"el/plus/cash-management.md"};function n(r,a,s,c,h,p){return l(),t("div",null,[...a[0]||(a[0]=[o('<h1 id="εισπραξη-και-παραδοση-μετρητων" tabindex="-1">Είσπραξη και παράδοση μετρητών <a class="header-anchor" href="#εισπραξη-και-παραδοση-μετρητων" aria-label="Permalink to &quot;Είσπραξη και παράδοση μετρητών&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">Έκδοση αναφοράς</p><p>Έλεγχος πηγαίου κώδικα TransferBook+ v0.7.26. Επιβεβαιώστε εγκατεστημένη έκδοση, εταιρεία, δικαιώματα και ρυθμίσεις. Χρησιμοποιήστε εγκεκριμένα συνθετικά δεδομένα για εκπαίδευση. Δεν επιβεβαιώνεται εμπορική ενεργοποίηση.</p></div><h2 id="εισπραξη-στη-διαδρομη" tabindex="-1">Είσπραξη στη διαδρομή <a class="header-anchor" href="#εισπραξη-στη-διαδρομη" aria-label="Permalink to &quot;Είσπραξη στη διαδρομή&quot;">​</a></h2><ol><li>Επιβεβαιώστε εξουσιοδοτημένο οδηγό, κράτηση και ανεξάρτητο σκέλος. Ελέγξτε το επαληθευμένο υπόλοιπο πριν την είσπραξη.</li><li>Καταχωρίστε μόνο τα μετρητά που πραγματικά παραλάβατε, μερική εξόφληση ή υπόλοιπο. Επιβεβαιώστε μία φορά και ελέγξτε απόδειξη και νέο υπόλοιπο. Μην καταχωρίζετε πριν την παραλαβή και μην επαναλαμβάνετε αβέβαιη υποβολή.</li><li>Η εγγραφή αναφέρει τον οδηγό που εισέπραξε και εκκρεμεί φυσική παράδοση στο γραφείο. Η εξόφληση επιβάτη και η φύλαξη μετρητών στο γραφείο είναι διαφορετικά γεγονότα.</li></ol><h2 id="κλεισιμο-ταμειου" tabindex="-1">Κλείσιμο ταμείου <a class="header-anchor" href="#κλεισιμο-ταμειου" aria-label="Permalink to &quot;Κλείσιμο ταμείου&quot;">​</a></h2><ol><li>Στον εγκεκριμένο χώρο πληρωμών ελέγξτε αποδείξεις μετρητών, αρχικό οδηγό είσπραξης και προηγούμενες παραδόσεις.</li><li>Μετρήστε τα φυσικά μετρητά και αντιστοιχίστε το πλήρες ποσό απόδειξης. Επιβεβαιώστε παράδοση μόνο μετά την πραγματική μεταφορά στο γραφείο. Αν υπάρχει διαφορά, διερευνήστε την.</li><li>Διαφορετικός κάτοχος απαιτεί εξουσιοδοτημένο έλεγχο company_admin και τεκμηριωμένο λόγο μεταβίβασης φύλαξης. Το backend απορρίπτει μη επιτρεπόμενη αντιστοίχιση ή διπλή παράδοση.</li><li>Επαληθεύστε εγγραφή παράδοσης και συμφωνήστε με αποδείξεις, πληρωμές και επιστροφές. Συγκεντρωτικός δείκτης δεν αποτελεί έγκυρο ταμείο.</li></ol><p>Χρησιμοποιήστε εγκεκριμένα συνθετικά δεδομένα για δοκιμές. Η έγκριση πληρωμής, το τιμολόγιο, ο σύνδεσμος checkout και ο δείκτης εκκρεμοτήτων δεν ισοδυναμούν με είσπραξη. Σε αβεβαιότητα ή διαφορά ποσού σταματήστε και διερευνήστε πριν από επανάληψη.</p><p>Δείτε <a href="/el/plus/payments-and-reconciliation.html">Πληρωμές</a> και <a href="/el/plus/chauffeur-workspace.html">Χώρος οδηγού</a>.</p>',8)])])}const _=e(i,[["render",n]]);export{d as __pageData,_ as default};
